function HomeCtrl:GetServerAddress()
    HttpNetworkManager.GetServerAddress(ServerType[1], function(data)
        print("_____GetServerAddress__111"..tostring(data)..tostring(type(data)))
        local tData = cjson.decode(tostring(data));
        HttpNetworkManager.lobbyAddress = string.format("%s:%s", tData.server.host, tData.server.port)
    end)
    HttpNetworkManager.GetServerAddress(ServerType[2], function(data)
        print("____GetServerAddress___2222"..tostring(data)..tostring(type(data)))
        local tData = cjson.decode(tostring(data));
        HttpNetworkManager.matchAddress = string.format("%s:%s", tData.server.host, tData.server.port)
    end)
end

function HomeCtrl:OnDestroy()
